 static void tick(Activity a,boolean pip,boolean chrome){try{JSONObject stream=TrackSelection.stream(a);if(stream==null||stream.optString("emby.item").isEmpty()){clear(a);return;}EmbyPlayerUi ui=ALL.get(a);if(ui==null){ui=new EmbyPlayerUi(a);ALL.put(a,ui);}ui.poll(stream,pip,chrome);}catch(Exception ignored){}}
 static void clear(Activity a){EmbyPlayerUi ui=ALL.remove(a);if(ui!=null)ui.dismiss();}
 static boolean ownsNext(Activity a){EmbyPlayerUi ui=ALL.get(a);return ui!=null&&ui.seriesNext()!=null;}
