 void prepare(JSONObject stream){
  dismiss();item=stream.optString("emby.item");audio=stream.optJSONArray("emby.audio");if(audio==null)audio=new JSONArray();subs=stream.optJSONArray("emby.subs");if(subs==null)subs=new JSONArray();versions=stream.optJSONArray("emby.versions");if(versions==null)versions=new JSONArray();
  JSONArray raw=stream.optJSONArray("emby.chapters");span=EmbyCue.spans(raw);try{chapters=EmbyCue.chapters(raw);}catch(Exception e){chapters=new JSONArray();}
  bifTried=false;appliedPref=false;cancelledNext=false;skipShownAt=-1;skipLabel=null;loadBif(stream);
 }
 int duration(){try{Object video=OnlineSubtitleSearch.field(a,"video");Object r=video==null?null:OnlineSubtitleSearch.call(video,"getDuration",new Class<?>[0]);int d=r instanceof Integer?(Integer)r:-1;if(d>0)return d;}catch(Exception ignored){}JSONObject stream=TrackSelection.stream(a);return (int)Math.min(Integer.MAX_VALUE,EmbyApi.ticksToMs(stream.optLong("emby.runtimeTicks")));}
