 void next(JSONObject stream,boolean chrome,int pos,int dur){
  String nextId=seriesNext();boolean enabled=PlaybackPrefs.autoNext(a.getSharedPreferences("data",0));
  boolean due=EmbyCue.nextDue(enabled,nextId!=null,cancelledNext,pos,dur,span.creditsStart);
  if(!due){if(!cancelledNext)nextShownAt=-1;hideNext();return;}
  if(nextCard==null){nextShownAt=SystemClock.elapsedRealtime();showNext((JSONObject)OnlineSubtitleSearch.field(a,"meta"),nextId);}
  int left=EmbyCue.countdownSeconds(SystemClock.elapsedRealtime()-nextShownAt);if(nextText!=null)nextText.setText("下一集 · "+AutoNextRules.label((JSONObject)OnlineSubtitleSearch.field(a,"meta"),nextId)+"\n"+left+" 秒后播放");
  if(left==0&&nextCard!=null){cancelledNext=true;hideNext();AutoNext.handoff(a,(JSONObject)OnlineSubtitleSearch.field(a,"meta"),nextId,String.valueOf(OnlineSubtitleSearch.field(a,"type")));}
 }
